import test from 'node:test';
import assert from 'node:assert/strict';
import { RATES, roundCents, formatEuros, parseEuros, convert, formatMoney } from '../src/money.js';

test('RATES constant has EUR, USD, GBP', () => {
  assert('EUR' in RATES);
  assert('USD' in RATES);
  assert('GBP' in RATES);
});

test('RATES EUR is 1', () => {
  assert.equal(RATES.EUR, 1);
});

test('RATES USD is 1.085', () => {
  assert.equal(RATES.USD, 1.085);
});

test('RATES GBP is 0.8425', () => {
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to EUR returns same amount', () => {
  const result = convert(10000, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10000);
});

test('convert EUR to USD multiplies by rate', () => {
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  const expected = Math.round(10000 * 1.085);
  assert.equal(result.value, expected);
});

test('convert EUR to GBP multiplies by rate', () => {
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  const expected = Math.round(10000 * 0.8425);
  assert.equal(result.value, expected);
});

test('convert returns integer cents', () => {
  const result = convert(12345, 'USD');
  assert(Number.isInteger(result.value));
});

test('convert rejects unknown currency', () => {
  const result = convert(10000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert zero amount', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert one cent EUR to USD', () => {
  const result = convert(1, 'USD');
  assert.equal(result.ok, true);
  assert(result.value >= 0);
});

test('convert 100 EUR to USD', () => {
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  const euros = 100;
  const expected = Math.round(euros * 100 * RATES.USD);
  assert.equal(result.value, expected);
});

test('convert 100 EUR to GBP', () => {
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  const euros = 100;
  const expected = Math.round(euros * 100 * RATES.GBP);
  assert.equal(result.value, expected);
});

test('convert large amount EUR to USD', () => {
  const result = convert(1000000, 'USD');
  assert.equal(result.ok, true);
  assert(result.value > 1000000);
});

test('convert uses roundCents for precision', () => {
  const result = convert(333, 'GBP');
  assert.equal(result.ok, true);
  assert(Number.isInteger(result.value));
});

test('convert case-sensitive currency', () => {
  const resultUpper = convert(10000, 'USD');
  const resultLower = convert(10000, 'usd');
  assert.equal(resultUpper.ok, true);
  assert.equal(resultLower.ok, false);
});

test('formatMoney EUR with €', () => {
  const result = formatMoney(12345, 'EUR');
  assert(result.includes('€'));
});

test('formatMoney USD with $', () => {
  const result = formatMoney(12345, 'USD');
  assert(result.includes('$'));
});

test('formatMoney GBP with £', () => {
  const result = formatMoney(12345, 'GBP');
  assert(result.includes('£'));
});

test('formatMoney formats with 2 decimals', () => {
  const result = formatMoney(12345, 'USD');
  assert(result.includes('.45'));
});

test('formatMoney pads cents with zero', () => {
  const result = formatMoney(10005, 'USD');
  assert(result.includes('.05'));
});

test('formatMoney includes thousands separator', () => {
  const result = formatMoney(123456, 'USD');
  assert(result.includes(','));
});

test('formatMoney 100 USD is $1,00.00', () => {
  const result = formatMoney(10000, 'USD');
  assert.equal(result, '$100.00');
});

test('formatMoney 1 GBP is £1.00', () => {
  const result = formatMoney(10000, 'GBP');
  assert.equal(result, '£100.00');
});

test('formatMoney 1 EUR is €1.00', () => {
  const result = formatMoney(10000, 'EUR');
  assert.equal(result, '€100.00');
});

test('formatMoney zero', () => {
  const result = formatMoney(0, 'USD');
  assert.equal(result, '$0.00');
});

test('formatMoney one cent', () => {
  const result = formatMoney(1, 'USD');
  assert.equal(result, '$0.01');
});

test('formatMoney negative amount', () => {
  const result = formatMoney(-12345, 'USD');
  assert(result.includes('-'));
  assert(result.includes('$'));
});

test('formatMoney negative with sign first', () => {
  const result = formatMoney(-10000, 'USD');
  assert.equal(result, '-$100.00');
});

test('formatMoney large amount', () => {
  const result = formatMoney(1234567, 'USD');
  assert.equal(result, '$12,345.67');
});

test('formatMoney with different currencies', () => {
  const cents = 50000;
  const eur = formatMoney(cents, 'EUR');
  const usd = formatMoney(cents, 'USD');
  const gbp = formatMoney(cents, 'GBP');

  assert(eur.includes('€'));
  assert(usd.includes('$'));
  assert(gbp.includes('£'));
});

test('convert and formatMoney integration', () => {
  const eurCents = 10000;
  const convertResult = convert(eurCents, 'USD');
  assert.equal(convertResult.ok, true);

  const formatted = formatMoney(convertResult.value, 'USD');
  assert(formatted.includes('$'));
  assert(formatted.includes('.'));
});

test('convert round-trip EUR to USD and back', () => {
  const eurCents = 10000;
  const toUsd = convert(eurCents, 'USD');
  assert.equal(toUsd.ok, true);

  const usdCents = toUsd.value;
  const usdRate = RATES.USD;
